#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<long long> blockSums(max_threads, 0);
    std::vector<long long> blockOffsets(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const int start = (tid * n) / nt;
        const int end   = ((tid + 1) * n) / nt;

        long long local = 0;
        for (int i = start; i < end; ++i) {
            local += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local); // local prefix within block
        }
        blockSums[tid] = local;

        #pragma omp barrier

        #pragma omp single
        {
            long long carry = 0;
            for (int t = 0; t < nt; ++t) {
                blockOffsets[t] = carry;
                carry += blockSums[t];
            }
        }

        const long long offset = blockOffsets[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
        }
    }
}
