#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    // Per-index scratch to avoid any shared-location write races.
    std::vector<long long> prefix(n, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const int start = (tid * n) / nt;
        const int end   = ((tid + 1) * n) / nt;

        // Local prefix inside this thread's contiguous block.
        long long local_sum = 0;
        for (int i = start; i < end; ++i) {
            local_sum += static_cast<long long>(x[i]);
            prefix[i] = local_sum;
        }

        // Ensure every thread's last element is available before reading.
        #pragma omp barrier

        // Compute offset as sum of all prior blocks' totals by reading only
        // each prior block's last prefix value (single writer per location).
        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            const int t_start = (t * n) / nt;
            const int t_end   = ((t + 1) * n) / nt;
            if (t_end > t_start) {
                offset += prefix[t_end - 1];
            }
        }

        // Finalize this block.
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(prefix[i] + offset);
        }
    }
}
